function render(){renderNav();renderContent();$('#noteCategory').innerHTML=categoryOptions(QUICK_NOTE_CATEGORY);$('#quickCategory').innerHTML=categoryOptions(QUICK_NOTE_CATEGORY);translateUI();if(!$('#dashboard').hidden)renderDashboard();requestAnimationFrame(updateScrollUI)}
function dashboardRecentNotes(){return state.people.flatMap(person=>person.notes.map(note=>({...note,person}))).sort((a,b)=>b.createdAt-a.createdAt).slice(0,4)}
function renderDashboard(){const currentPerson=$('#dashboardCurrentPerson'),current=state.people.find(p=>p.id===selectedId)||state.people[0];if(currentPerson)currentPerson.textContent=current?.name||localizedText('Open workspace');$('#dashboardRecentNotes').innerHTML=dashboardRecentNotes().map((note,index)=>`<button class="dashboard-note" data-dashboard-person="${note.person.id}" style="--note-index:${index}"><span class="dashboard-note-avatar" ${avatarStyle(note.person)}>${avatarContent(note.person)}</span><span><strong>${esc(note.text)}</strong><small>${esc(note.person.name)} · ${esc(localizedCategoryLabel(CATEGORIES[note.category]?.label||note.category))}</small></span><time>${relativeTime(note.createdAt)}</time><i>→</i></button>`).join('')||`<div class="dashboard-empty">${localizedText('No notes yet')}</div>`;document.querySelectorAll('[data-dashboard-lang]').forEach(button=>button.classList.toggle('active',button.dataset.dashboardLang===state.settings.language));document.querySelectorAll('[data-dashboard-person]').forEach(button=>button.onclick=()=>openWorkspace(button.dataset.dashboardPerson));translateUI($('#dashboard'))}
function todoDateLabelValue(date){if(!date)return'';return new Intl.DateTimeFormat(state.settings.language==='ru'?'ru-RU':'en-GB',{day:'numeric',month:'short'}).format(new Date(`${date}T12:00:00`))}
function todoSidebarItem(view,label,iconName,count){return QuickNotesUI.sidebarItem({person:{id:view,name:localizedText(label),notes:[]},active:todoView===view,avatarStyle:()=>'',avatarContent:()=>QuickNotesTodo.icon(iconName),profileMeta:()=>'',escape:esc,attributes:`data-todo-nav="${view}"`,classes:'todo-sidebar-item',count:count??''})}
function renderTodoNav(){const items=[['current','Current','all'],['recent','Recent','recent'],['pinned','Pinned','pin'],['deadline','With deadline','calendar'],['focus','In focus','star'],['standalone','Single tasks','task'],['all-lists','All lists','list']];const counts={pinned:state.todo.lists.filter(x=>x.pinned).length,deadline:state.todo.lists.filter(x=>x.dueDate).length+QuickNotesTodo.standaloneTasks(state.todo).filter(x=>x.dueDate).length,focus:state.todo.tasks.filter(x=>x.starred&&!x.completed).length,standalone:QuickNotesTodo.standaloneTasks(state.todo).length,'all-lists':state.todo.lists.length};$('#todoNav').innerHTML=`<p class="todo-nav-label">TO DO BOARD</p>${items.map(([view,label,icon],index)=>`${index===5?'<span class="todo-nav-divider"></span>':''}${todoSidebarItem(view,label,icon,counts[view])}`).join('')}`;document.querySelectorAll('[data-todo-nav]').forEach(button=>button.onclick=()=>{todoView=button.dataset.todoNav;todoBulkMode=false;todoBulkSelected.clear();$('#sidebar').classList.remove('open');renderTodo()});translateUI($('#todoSidebarContent'))}
function todoListActivity(list){const child=QuickNotesTodo.listTasks(state.todo,list.id);return Math.max(list.updatedAt||0,...child.map(x=>x.updatedAt||x.createdAt||0),0)}
function todoSortLists(lists,mode=todoListSort){const arr=[...lists];if(mode==='least-used')return arr.sort((a,b)=>todoListActivity(a)-todoListActivity(b));if(mode==='deadline'||mode==='deadline-desc')return arr.sort((a,b)=>{const cmp=(a.dueDate||'9999-99-99').localeCompare(b.dueDate||'9999-99-99');return (mode==='deadline-desc'?-cmp:cmp)||todoListActivity(b)-todoListActivity(a)});return arr.sort((a,b)=>todoListActivity(b)-todoListActivity(a))}
function todoSortStandalone(tasks,mode=todoTaskSort){const arr=[...tasks];if(mode==='oldest')return arr.sort((a,b)=>(a.updatedAt||a.createdAt)-(b.updatedAt||b.createdAt));if(mode==='deadline'||mode==='deadline-desc')return arr.sort((a,b)=>{const cmp=(a.dueDate||'9999-99-99').localeCompare(b.dueDate||'9999-99-99');return (mode==='deadline-desc'?-cmp:cmp)||(b.updatedAt||b.createdAt)-(a.updatedAt||a.createdAt)});return arr.sort((a,b)=>(b.updatedAt||b.createdAt)-(a.updatedAt||a.createdAt))}
function todoListMenu(list){return `<span class="todo-card-menu-wrap"><button class="more-btn" type="button" data-menu-toggle="todo-list-menu-${list.id}" aria-expanded="false" aria-label="List actions">•••</button><span class="action-menu todo-object-menu" id="todo-list-menu-${list.id}" hidden><button type="button" class="menu-danger" data-todo-list-delete="${list.id}">Delete</button></span></span>`}
function todoListCard(list,{compact=false,selectable=false}={}){const tasks=QuickNotesTodo.sortListTasks(QuickNotesTodo.listTasks(state.todo,list.id),'manual'),progress=QuickNotesTodo.progress(state.todo,list.id),shown=tasks.slice(0,compact?2:3),selected=todoBulkSelected.has(list.id);const quickActions=!selectable&&!compact?`<button class="icon-only todo-card-date ${list.dueDate?'active':''}" type="button" data-todo-card-date="${list.id}" data-tooltip="${list.dueDate?'Change date':'Date'}" aria-label="${list.dueDate?'Change date':'Date'}">${QuickNotesTodo.icon('calendar')}</button><button class="icon-only todo-card-pin ${list.pinned?'active':''}" type="button" data-todo-card-pin="${list.id}" data-tooltip="${list.pinned?'Unpin':'Pin'}" aria-label="${list.pinned?'Unpin':'Pin'}">${QuickNotesTodo.icon('pin')}</button>`:'';return `<article class="todo-list-card icon-${list.icon} ${compact?'compact':''} ${selectable?'selectable':''} ${selected?'selected':''}" data-open-todo-list="${list.id}">${selectable?`<button class="bulk-check ${selected?'active':''}" type="button" data-bulk-list="${list.id}" aria-pressed="${selected}"><span>${selected?'✓':''}</span></button>`:''}<header><span class="todo-list-card-icon">${QuickNotesTodo.icon(list.icon)}</span><div class="todo-list-card-title"><h3>${esc(list.name)}</h3>${list.dueDate?`<time>${QuickNotesTodo.icon('calendar')} ${esc(todoDateLabelValue(list.dueDate))}</time>`:''}</div>${compact&&list.pinned?`<span class="todo-pin-mark" data-tooltip="Pinned" aria-label="Pinned">${QuickNotesTodo.icon('pin')}</span>`:''}${quickActions}${!selectable?todoListMenu(list):''}</header><div class="todo-list-preview">${shown.length?shown.map(task=>`<div class="todo-preview-task ${task.completed?'completed':''}"><span>${task.completed?'✓':'○'}</span><p>${esc(task.text)}</p></div>`).join(''):`<p class="todo-list-empty-preview">${localizedText('Empty list')}</p>`}</div><footer><span>${progress.completed} / ${progress.total} ${localizedText('done')}</span><span class="todo-progress"><i style="width:${progress.total?Math.round(progress.completed/progress.total*100):0}%"></i></span></footer></article>`}
function todoTaskMenu(task){return `<span class="todo-task-menu-wrap"><button class="more-btn" type="button" data-menu-toggle="todo-task-menu-${task.id}" aria-expanded="false" aria-label="Task actions">•••</button><span class="action-menu todo-object-menu" id="todo-task-menu-${task.id}" hidden>${!task.listId?`<button type="button" data-todo-task-edit-dialog="${task.id}">Edit details</button>`:''}<button type="button" class="menu-danger" data-todo-task-delete="${task.id}">Delete</button></span></span>`}
function todoStandaloneRow(task,{selectable=false,showSource=false}={}){const selected=todoBulkSelected.has(task.id),source=task.listId?state.todo.lists.find(x=>x.id===task.listId):null;return `<article class="todo-standalone-row ${task.completed?'completed':''} ${selectable?'selectable':''} ${selected?'selected':''}" data-todo-task-row="${task.id}">${selectable?`<button class="bulk-check ${selected?'active':''}" type="button" data-bulk-task="${task.id}" aria-pressed="${selected}"><span>${selected?'✓':''}</span></button>`:`<button class="todo-task-check" type="button" data-todo-check="${task.id}" aria-label="${task.completed?'Mark active':'Complete task'}"><span class="todo-task-dot"></span></button>`}<button class="todo-inline-task-text" type="button" data-inline-task="${task.id}">${esc(task.text)}</button>${showSource&&source?`<small class="todo-task-source">${esc(source.name)}</small>`:''}${task.dueDate?`<time>${esc(todoDateLabelValue(task.dueDate))}</time>`:''}${!selectable?`<button class="todo-task-star ${task.starred?'active':''}" type="button" data-todo-star="${task.id}" aria-pressed="${task.starred}" aria-label="${task.starred?'Remove from focus':'Add to focus'}">${QuickNotesTodo.icon('star')}</button>${todoTaskMenu(task)}`:''}</article>`}
function todoSectionHeading(label,icon,classes='todo-current-section-head'){return `<div class="${classes}"><span class="${classes.includes('todo-current')?'todo-current-section-icon':'todo-view-heading-icon'}">${QuickNotesTodo.icon(icon)}</span><h2>${esc(localizedText(label))}</h2></div>`}
function todoObjectPocket(markup,type){return `<div class="todo-object-pocket todo-object-pocket-${type}">${markup}</div>`}
function todoMixedMarkup(lists,tasks,{compact=false}={}){if(!lists.length&&!tasks.length)return `<div class="todo-zone-empty">${localizedText('Nothing here yet')}</div>`;if(todoView==='current'){const listZone=lists.length?`<section class="todo-lists-zone"><div class="todo-list-grid">${lists.map(list=>todoObjectPocket(todoListCard(list,{compact}),'list')).join('')}</div></section>`:'';const taskZone=tasks.length?`<aside class="todo-tasks-zone"><div class="todo-task-column">${tasks.map(task=>todoObjectPocket(todoStandaloneRow(task),'task')).join('')}</div></aside>`:'';return `<div class="todo-planner-spread ${!lists.length?'tasks-only':''} ${!tasks.length?'lists-only':''}">${listZone}${taskZone}</div>`}const columns=[[],[]];lists.forEach((list,index)=>columns[index%2].push(todoObjectPocket(todoListCard(list,{compact}),'list')));return `<div class="todo-fixed-layout todo-fixed-layout-mixed"><div class="todo-fixed-column todo-fixed-column-list">${columns[0].join('')||'<div class="todo-slot-empty"></div>'}</div><div class="todo-fixed-column todo-fixed-column-list">${columns[1].join('')||'<div class="todo-slot-empty"></div>'}</div><div class="todo-fixed-column todo-fixed-column-task">${tasks.length?tasks.map(task=>todoObjectPocket(todoStandaloneRow(task),'task')).join(''):'<div class="todo-slot-empty"></div>'}</div></div>`}
function todoCurrentMarkup(data){const listSection=(key,label,icon,lists)=>`<section class="todo-current-section todo-current-${key} ${lists.length?`items-${Math.min(lists.length,3)}`:'is-empty'}">${todoSectionHeading(label,icon)}<div class="todo-current-pocket">${lists.length?`<div class="todo-current-cards">${lists.map(list=>todoListCard(list,{compact:true})).join('')}</div>`:`<div class="todo-current-folded-empty">${localizedText('Nothing here yet')}</div>`}</div></section>`;return `<div class="todo-current-board todo-current-main-only"><div class="todo-current-left">${[listSection('pinned','Pinned','pin',data.pinned),listSection('deadline','With deadline','calendar',data.deadline),listSection('recent','Recent','recent',data.recent)].join('')}</div></div>`}
function todoCurrentFocusMarkup(data){return `<aside class="todo-current-focus ${data.focusTasks.length?`items-${Math.min(data.focusTasks.length,3)}`:'is-empty'}">${todoSectionHeading('In focus','star')}<div class="todo-current-focus-pocket">${data.focusTasks.length?`<div class="todo-task-column">${data.focusTasks.map(task=>todoStandaloneRow(task,{showSource:true})).join('')}</div>`:`<div class="todo-current-folded-empty">${localizedText('Nothing here yet')}</div>`}</div></aside>`}
function todoCurrentData(){const pinned=todoSortLists(state.todo.lists.filter(x=>x.pinned),'recent').slice(0,3),used=new Set(pinned.map(x=>x.id)),deadline=todoSortLists(state.todo.lists.filter(x=>x.dueDate&&!used.has(x.id)),'deadline').slice(0,3);deadline.forEach(x=>used.add(x.id));const recent=todoSortLists(state.todo.lists.filter(x=>!used.has(x.id)),'recent').slice(0,3),focusTasks=state.todo.tasks.filter(x=>x.starred&&!x.completed).sort((a,b)=>(b.updatedAt||b.createdAt)-(a.updatedAt||a.createdAt)).slice(0,3);return{pinned,deadline,recent,focusTasks}}
function todoFilterSearch(){const q=todoSearchTerm.toLowerCase();if(!q)return null;const matchingTasks=state.todo.tasks.filter(task=>task.text.toLowerCase().includes(q)),taskListIds=new Set(matchingTasks.filter(x=>x.listId).map(x=>x.listId)),lists=state.todo.lists.filter(list=>list.name.toLowerCase().includes(q)||taskListIds.has(list.id)),standalone=matchingTasks.filter(x=>!x.listId);return{lists,tasks:standalone}}
function todoViewData(){const search=todoFilterSearch();if(search){if(todoView==='all-lists')return{kind:'lists',title:'Search results',lists:search.lists,bulk:true};if(todoView==='standalone')return{kind:'tasks',title:'Search results',tasks:search.tasks,bulk:true};return{kind:'mixed',title:'Search results',...search}}if(todoView==='current')return{kind:'current',title:'Current',...todoCurrentData()};if(todoView==='recent')return{kind:'mixed',title:'Recent',lists:todoSortLists(state.todo.lists,'recent').slice(0,10),tasks:todoSortStandalone(QuickNotesTodo.standaloneTasks(state.todo),'recent').slice(0,10)};if(todoView==='pinned')return{kind:'lists',title:'Pinned',lists:todoSortLists(state.todo.lists.filter(x=>x.pinned),'recent')};if(todoView==='deadline')return{kind:'mixed',title:'With deadline',lists:todoSortLists(state.todo.lists.filter(x=>x.dueDate),todoListSort==='deadline-desc'?'deadline-desc':'deadline'),tasks:todoSortStandalone(QuickNotesTodo.standaloneTasks(state.todo).filter(x=>x.dueDate),todoListSort==='deadline-desc'?'deadline-desc':'deadline')};if(todoView==='focus')return{kind:'tasks',title:'In focus',tasks:state.todo.tasks.filter(x=>x.starred&&!x.completed).sort((a,b)=>(b.updatedAt||b.createdAt)-(a.updatedAt||a.createdAt)),showSource:true};if(todoView==='standalone')return{kind:'tasks',title:'Single tasks',tasks:todoSortStandalone(QuickNotesTodo.standaloneTasks(state.todo),todoTaskSort),bulk:true};return{kind:'lists',title:'All lists',lists:todoSortLists(state.todo.lists,todoListSort),bulk:true}}
function todoSortControl(){if(todoSearchTerm)return'';let options=[],value='',label='';if(todoView==='all-lists'){value=todoListSort;options=[['recent','Last activity'],['least-used','Not used recently'],['deadline','Nearest deadline']]}else if(todoView==='standalone'){value=todoTaskSort;options=[['recent','Newest activity'],['oldest','Oldest activity'],['deadline','Deadline first']]}else return'';label=options.find(([key])=>key===value)?.[1]||options[0][1];return `<span class="todo-sort-wrap"><button class="secondary todo-sort-toggle" type="button" data-menu-toggle="todo-sort-menu" aria-expanded="false"><span>${esc(localizedText(label))}</span><b aria-hidden="true">⌄</b></button><span class="action-menu todo-sort-menu" id="todo-sort-menu" hidden>${options.map(([key,text])=>`<button type="button" class="${key===value?'active':''}" data-todo-sort="${key}">${esc(localizedText(text))}${key===value?'<span>✓</span>':''}</button>`).join('')}</span></span>`}
function todoViewMeta(view=todoView){const map={recent:['Recent','recent'],pinned:['Pinned','pin'],deadline:['With deadline','calendar'],focus:['In focus','star'],standalone:['Single tasks','task'],'all-lists':['All lists','list']};return map[view]||['Current','all']}
function todoViewHeadingMarkup(title){const [fallback,icon]=todoViewMeta();return `<div class="todo-view-heading todo-view-heading-${todoView}">${todoSectionHeading(title||fallback,icon,'todo-view-title-line')}${todoSearchTerm?`<small>${localizedText('Showing matches for')} “${esc(todoSearchTerm)}”</small>`:''}</div>`}
function syncTodoCurrentGeometry(){
 const page=$('#todoPage');
 if(!page||todoView!=='current'||page.hidden)return;
 const left=page.querySelector('.todo-current-left'),rail=$('#todoSideRail'),actions=$('#todoCreateActions'),focus=$('#todoSideRailContent'),title=$('#todoTopbarTitle');
 if(!left||!rail||!actions||!focus)return;
 left.style.removeProperty('--todo-current-left-height');actions.style.marginTop='';focus.style.marginTop='';
 requestAnimationFrame(()=>{
  const leftRect=left.getBoundingClientRect(),pageStyle=getComputedStyle(page);
  const edgeGap=Math.max(14,Math.round(parseFloat(pageStyle.paddingBottom)||18));
  const available=Math.max(0,Math.floor(window.innerHeight-leftRect.top-edgeGap));
  left.style.setProperty('--todo-current-left-height',`${available}px`);
  requestAnimationFrame(()=>{
   const pinnedPocket=left.querySelector('.todo-current-pinned .todo-current-pocket'),deadlineHead=left.querySelector('.todo-current-deadline .todo-current-section-head');
   if(!pinnedPocket||!deadlineHead)return;
   const railTop=rail.getBoundingClientRect().top;
   actions.style.marginTop=`${Math.max(0,Math.round(pinnedPocket.getBoundingClientRect().top-railTop))}px`;
   const actionsBottom=actions.getBoundingClientRect().bottom;
   focus.style.marginTop=`${Math.max(0,Math.round(deadlineHead.getBoundingClientRect().top-actionsBottom))}px`;
  });
 });
}
function placeTodoCreateActions(){const actions=$('#todoCreateActions'),rail=$('#todoSideRail'),railContent=$('#todoSideRailContent'),headerHost=$('#todoHeaderActions');if(!actions||!rail||!railContent||!headerHost)return;if(todoView==='current'){if(actions.parentElement!==rail)rail.insertBefore(actions,railContent);rail.hidden=false}else{if(actions.parentElement!==headerHost)headerHost.appendChild(actions);rail.hidden=true}}
