function deleteTodoList(id){const index=state.todo.lists.findIndex(x=>x.id===id);if(index<0)return;const list=structuredClone(state.todo.lists[index]),tasks=structuredClone(state.todo.tasks.filter(x=>x.listId===id)),wasOpen=todoView===`list:${id}`;state.todo.lists.splice(index,1);state.todo.tasks=state.todo.tasks.filter(x=>x.listId!==id);if(wasOpen){todoView=todoReturnContext.view||'all-lists';todoSearchTerm=todoReturnContext.search||''}save();renderTodo();actionToast('List deleted',()=>{state.todo.lists.splice(Math.min(index,state.todo.lists.length),0,list);state.todo.tasks.push(...tasks);save();renderTodo()})}
