function bindOpenListEvents(list,tasks){$('#todoBackToLists').onclick=()=>{todoView=todoReturnContext.view||'all-lists';todoSearchTerm=todoReturnContext.search||'';if($('#todoSearchInput'))$('#todoSearchInput').value=todoSearchTerm;if($('#todoSearchClearBtn'))$('#todoSearchClearBtn').hidden=!todoSearchTerm;renderTodo()};$('#todoEditListTitle').onclick=()=>startTodoListTitleEdit(list);$('#todoListDateBtn').onclick=e=>pickTodoListDate(list,e.currentTarget);$('#todoOpenPin').onclick=()=>{list.pinned=!list.pinned;list.updatedAt=Date.now();save();renderTodo()};$('#todoListSortBtn')?.addEventListener('click',()=>{list.sortMode=list.sortMode==='manual'?'active-first':list.sortMode==='active-first'?'completed-first':'manual';save();renderTodo()});document.querySelectorAll('[data-menu-toggle]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleMenu(b)});document.querySelectorAll('[data-todo-list-delete]').forEach(b=>b.onclick=e=>{e.stopPropagation();deleteTodoList(list.id)});document.querySelectorAll('[data-todo-check]').forEach(b=>b.onclick=e=>{e.stopPropagation();const task=state.todo.tasks.find(x=>x.id===b.dataset.todoCheck);if(task)setTodoTaskCompleted(task.id,!task.completed)});document.querySelectorAll('[data-todo-star]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleTodoStar(b.dataset.todoStar)});document.querySelectorAll('[data-inline-task]').forEach(b=>b.onclick=e=>{e.stopPropagation();startInlineTaskEdit(b.dataset.inlineTask,b)});document.querySelectorAll('[data-todo-task-delete]').forEach(b=>b.onclick=e=>{e.stopPropagation();deleteTodoTask(b.dataset.todoTaskDelete)});document.querySelectorAll('.todo-task-drag').forEach(handle=>handle.onpointerdown=()=>{todoDragArmed=handle.closest('[data-list-task-row]')?.dataset.listTaskRow||''});document.querySelectorAll('[data-list-task-row]').forEach(row=>{row.ondragstart=e=>{if(todoDragArmed!==row.dataset.listTaskRow){e.preventDefault();return}e.dataTransfer.setData('text/plain',row.dataset.listTaskRow);row.classList.add('dragging')};row.ondragend=()=>{todoDragArmed='';row.classList.remove('dragging')};row.ondragover=e=>{e.preventDefault();row.classList.add('drag-over')};row.ondragleave=()=>row.classList.remove('drag-over');row.ondrop=e=>{e.preventDefault();row.classList.remove('drag-over');const from=e.dataTransfer.getData('text/plain'),to=row.dataset.listTaskRow;if(!from||from===to)return;const manual=[...QuickNotesTodo.listTasks(state.todo,list.id)].sort((a,b)=>a.order-b.order),fromIndex=manual.findIndex(x=>x.id===from),toIndex=manual.findIndex(x=>x.id===to);if(fromIndex<0||toIndex<0)return;const [moved]=manual.splice(fromIndex,1);manual.splice(toIndex,0,moved);manual.forEach((task,index)=>task.order=index);list.updatedAt=Date.now();save();renderTodo()}});const input=$('#todoNewListTask');input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();const value=input.value.trim();if(!value)return;addTasksToList(list.id,[value]);input.value=''}};input.onpaste=e=>{const text=e.clipboardData?.getData('text/plain')||'',lines=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(lines.length>1){e.preventDefault();addTasksToList(list.id,lines)}}}
function addTasksToList(listId,texts){const existing=QuickNotesTodo.listTasks(state.todo,listId),count=texts.length,now=Date.now();existing.forEach(task=>task.order=(Number.isFinite(task.order)?task.order:0)+count);texts.forEach((text,index)=>state.todo.tasks.push({id:QuickNotesTodo.uid('todo'),text,listId,completed:false,starred:false,dueDate:'',order:index,createdAt:now+index,updatedAt:now+index}));QuickNotesTodo.touchList(state.todo,listId);save();renderTodo();setTimeout(()=>$('#todoNewListTask')?.focus(),20)}
