function releaseRepository(){const cfg=window.QuickNotesReleaseConfig||{};if(cfg.githubOwner&&cfg.githubRepo)return{owner:cfg.githubOwner,repo:cfg.githubRepo};const host=location.hostname.toLowerCase();if(host.endsWith('.github.io')){const owner=host.slice(0,-'.github.io'.length),parts=location.pathname.split('/').filter(Boolean),repo=parts[0]||`${owner}.github.io`;return{owner,repo}}return null}
async function latestWebInstaller(){const repo=releaseRepository(),assetName=window.QuickNotesReleaseConfig?.installerAsset||'Quick-Notes-Setup.exe';if(!repo)return{ok:false,reason:'repository-not-configured'};try{const response=await fetch(`https://api.github.com/repos/${repo.owner}/${repo.repo}/releases/latest`,{headers:{Accept:'application/vnd.github+json'}});if(!response.ok)throw new Error(`GitHub returned ${response.status}`);const release=await response.json(),asset=(release.assets||[]).find(item=>item.name===assetName)||(release.assets||[]).find(item=>/\.exe$/i.test(item.name));return asset?{ok:true,url:asset.browser_download_url,version:String(release.tag_name||release.name||'').replace(/^v/i,'')}:{ok:false,reason:'installer-not-found'}}catch(error){return{ok:false,reason:'network-error',error}}}
function distributionButton(){return $('#dashboardInstallUpdate')}
function setDistributionVisibility(visible){const button=distributionButton();if(!button)return;button.hidden=!visible;button.style.display=visible?'':'none'}
function setDistributionButton(label,{disabled=false,state='',ready=false,visible=true}={}){const button=distributionButton(),copy=$('#dashboardInstallUpdateLabel');if(!button||!copy)return;setDistributionVisibility(visible);copy.textContent=localizedText(label);button.disabled=disabled;button.dataset.updateState=state;button.classList.toggle('is-ready',ready)}
function applyRuntimeMode(){if(!IS_DESKTOP)return;const sidebarStatus=document.querySelector('.web-demo-status');if(sidebarStatus)sidebarStatus.innerHTML='<span>●</span><div><strong>Desktop app</strong><small>Saved locally on this computer</small></div>';const footerStatus=document.querySelector('.dashboard-footer>span');if(footerStatus)footerStatus.innerHTML='<i></i> Desktop app · Saved locally on this computer';const footerButton=document.querySelector('.dashboard-footer>button');if(footerButton){footerButton.disabled=false;footerButton.textContent='Open data folder';footerButton.onclick=()=>window.quickNotesDesktop.openDataFolder()}}
async function onDistributionClick(){const button=distributionButton();if(!button||button.disabled)return;if(!IS_DESKTOP){setDistributionButton('Finding…',{disabled:true,state:'checking'});const result=await latestWebInstaller();setDistributionButton('Install',{state:'install'});if(result.ok){location.href=result.url;return}toast(result.reason==='repository-not-configured'?'GitHub release is not configured yet':'Installer is not available yet');return}if(button.dataset.updateState==='downloaded'){await window.quickNotesDesktop.openDownloadedUpdate();return}if(button.dataset.updateState!=='available')return;setDistributionButton(`${localizedText('Update')} 0%`,{disabled:true,state:'downloading'});const result=await window.quickNotesDesktop.downloadUpdate();if(!result?.ok)setDistributionButton('Update',{state:'available',ready:true})}
function setupDistributionButton(){const button=distributionButton();if(!button)return;button.onclick=onDistributionClick;const demoInstall=$('#webDemoInstall');if(demoInstall)demoInstall.onclick=()=>{if($('#webDemoDialog')?.open)$('#webDemoDialog').close();onDistributionClick()};if(!IS_DESKTOP){setDistributionButton('Install',{state:'install',visible:true});return}setDistributionVisibility(false);const isPackaged=typeof window.quickNotesDesktop?.isPackaged==='function'?window.quickNotesDesktop.isPackaged():true;if(!isPackaged)return;window.quickNotesDesktop.onUpdateStatus(status=>{if(!status)return;if(status.state==='available'){setDistributionButton('Update',{state:'available',ready:true,visible:true});return}if(status.state==='downloading'){setDistributionButton(`${localizedText('Update')} ${Math.max(0,Math.min(100,status.percent||0))}%`,{disabled:true,state:'downloading',visible:true});return}if(status.state==='downloaded'){setDistributionButton('Open update',{state:'downloaded',ready:true,visible:true});toast('Update downloaded');return}if(status.state==='current'||status.state==='checking'||status.state==='error'||status.state==='unavailable'){setDistributionVisibility(false);return}});window.quickNotesDesktop.checkForUpdate()}
