function openNote(noteId=null,category=QUICK_NOTE_CATEGORY,unused=null,contextGroup=null,targetId=null){const source=state.people.flatMap(p=>p.notes.map(n=>({...n,personId:p.id}))).find(n=>n.id===noteId);noteContextGroup=source?.capturedInGroupId||contextGroup;$('#noteId').value=noteId||'';const resolvedTarget=source?.personId||targetId||'';notePickerController?.destroy();$('#notePersonPickerMount').innerHTML=capturePersonPickerMarkup({selectedId:resolvedTarget,inputId:'notePerson',pickerId:'notePersonPicker'});notePickerController=initCapturePersonPicker({pickerId:'notePersonPicker',onChange:updateNoteSaveState});$('#noteCategory').innerHTML=categoryOptions(source?.category||category);$('#noteText').value=source?.text||'';$('#noteDialogEyebrow').textContent=source?'EDIT NOTE':'NEW NOTE';$('#noteDialogTitle').textContent=source?'Edit observation':'Add an observation';$('#deleteNoteBtn').hidden=!source;translateUI($('#noteDialog'));updateNoteSaveState();$('#noteDialog').showModal();setTimeout(()=>$('#noteText').focus(),50)}
