function deleteNote(id){const record=findNoteRecord(id);if(!record)return;const snapshot=structuredClone(record.note),personId=record.person.id,index=record.index;record.person.notes.splice(index,1);save();render();actionToast('Note deleted',()=>{const person=state.people.find(item=>item.id===personId);if(!person||findNoteRecord(id))return;person.notes.splice(Math.min(index,person.notes.length),0,snapshot);save();render();toast('Note restored')})}
function closeMenus(){document.querySelectorAll('.move-submenu:not([hidden])').forEach(menu=>menu.hidden=true);document.querySelectorAll('[data-move-menu]').forEach(button=>button.setAttribute('aria-expanded','false'));document.querySelectorAll('.action-menu:not([hidden])').forEach(menu=>menu.hidden=true);document.querySelectorAll('[data-menu-toggle]').forEach(button=>button.setAttribute('aria-expanded','false'))}
