function removeCategorySetting(key){if(key===QUICK_NOTE_CATEGORY){toast('Quick Note cannot be deleted');return}const keys=Object.keys(categoryDraft);if(keys.length===1){alert(uiMessage('categoryRequired'));return}const used=state.people.reduce((sum,p)=>sum+p.notes.filter(n=>n.category===key).length,0);if(!used){delete categoryDraft[key];renderCategorySettings();return}pendingCategoryDelete=key;$('#deleteCategoryTitle').textContent=uiMessage('deleteCategoryTitle',{category:categoryDraft[key].label});$('#deleteCategoryCopy').textContent=uiMessage('deleteCategoryCopy',{count:used});$('#deleteCategoryTarget').innerHTML=keys.filter(id=>id!==key).map(id=>`<option value="${id}">${esc(categoryDraft[id].label)}</option>`).join('');$('#categoryDeleteDialog').showModal()}
function reorderCategory(from,to){if(from===to)return;const entries=Object.entries(categoryDraft),item=entries.splice(entries.findIndex(([id])=>id===from),1)[0],index=entries.findIndex(([id])=>id===to);entries.splice(index,0,item);categoryDraft=Object.fromEntries(entries);renderCategorySettings()}
function renderCategorySettings(){const box=$('#categorySettings'),entries=Object.entries(categoryDraft),atLimit=userCategoryCount(categoryDraft)>=MAX_USER_CATEGORIES,addButton=$('#addCategoryBtn');if(addButton){addButton.disabled=atLimit;addButton.setAttribute('aria-disabled',String(atLimit));addButton.dataset.tooltip=atLimit?'Maximum 8 categories':''}box.innerHTML=entries.map(([key,cat])=>{const system=key===QUICK_NOTE_CATEGORY,icon=QuickNotesCategoryIcons.svg(cat.icon);return `<div class="category-setting ${system?'system-category':''}" data-category-row="${key}"><span class="drag-handle" draggable="true" data-tooltip="Drag to reorder" aria-label="Drag to reorder">≡</span><button class="category-icon-button" type="button" ${system?'disabled aria-disabled="true"':`data-category-icon="${key}"`} aria-label="${esc(system?'Quick Note icon':`Choose icon for ${cat.label}`)}">${icon}</button><input value="${esc(system?'Quick Note':localizedCategoryLabel(cat.label))}" maxlength="30" data-category-name="${key}" aria-label="Category name" ${system?'readonly':''}>${system?'':`<button class="category-delete" type="button" data-category-delete="${key}" aria-label="Delete ${esc(cat.label)}">${ICONS.trash}</button>`}</div>`}).join('');box.querySelectorAll('[data-category-name]').forEach(input=>input.oninput=()=>{if(input.dataset.categoryName===QUICK_NOTE_CATEGORY){input.value='Quick Note';return}categoryDraft[input.dataset.categoryName].label=input.value});box.querySelectorAll('[data-category-icon]').forEach(button=>button.onclick=()=>openCategoryIconPicker(button.dataset.categoryIcon,button));box.querySelectorAll('[data-category-delete]').forEach(button=>button.onclick=()=>removeCategorySetting(button.dataset.categoryDelete));let dragged=null;box.querySelectorAll('[data-category-row]').forEach(row=>{row.querySelector('.drag-handle').ondragstart=e=>{dragged=row.dataset.categoryRow;row.classList.add('dragging');e.dataTransfer.effectAllowed='move'};row.ondragend=()=>{row.classList.remove('dragging');box.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'))};row.ondragover=e=>{e.preventDefault();row.classList.add('drag-over')};row.ondragleave=()=>row.classList.remove('drag-over');row.ondrop=e=>{e.preventDefault();reorderCategory(dragged,row.dataset.categoryRow)}});translateUI(box);QuickNotesTooltip.refresh(box)}
let categoryIconPickerKey='';
