function openCategoryIconPicker(key,anchor){if(key===QUICK_NOTE_CATEGORY||!categoryDraft[key])return;const picker=$('#categoryIconPicker');if(picker.parentElement!==$('#settingsDialog'))$('#settingsDialog').append(picker);categoryIconPickerKey=key;picker.innerHTML=`<div class="category-icon-picker-head"><strong>${esc(localizedText('Choose icon'))}</strong><button type="button" class="category-icon-picker-close" aria-label="Close">×</button></div><div class="category-icon-grid">${QuickNotesCategoryIcons.order.map(name=>`<button type="button" class="category-icon-choice ${QuickNotesCategoryIcons.normalize(categoryDraft[key].icon)===name?'active':''}" data-icon-choice="${name}" aria-label="${esc(QuickNotesCategoryIcons.labels[name])}">${QuickNotesCategoryIcons.svg(name)}</button>`).join('')}</div>`;picker.hidden=false;picker.classList.add('open');const rect=anchor.getBoundingClientRect(),dialog=$('#settingsDialog').getBoundingClientRect();requestAnimationFrame(()=>{const width=picker.offsetWidth,height=picker.offsetHeight;let left=rect.left,top=rect.bottom+8;if(left+width>innerWidth-12)left=Math.max(12,rect.right-width);if(top+height>innerHeight-12)top=Math.max(12,rect.top-height-8);picker.style.left=`${Math.round(left)}px`;picker.style.top=`${Math.round(top)}px`});picker.querySelector('.category-icon-picker-close').onclick=closeCategoryIconPicker;picker.querySelectorAll('[data-icon-choice]').forEach(button=>button.onclick=()=>{categoryDraft[key].icon=button.dataset.iconChoice;closeCategoryIconPicker();renderCategorySettings()});translateUI(picker)}

