$('#settingsForm').onsubmit=e=>{e.preventDefault();categoryDraft=normalizeCategories(categoryDraft);const labels=Object.values(categoryDraft).map(c=>c.label.trim());if(labels.some(label=>!label)){toast('Category names cannot be empty');return}if(new Set(labels.map(x=>x.toLowerCase())).size!==labels.length){toast('Category names must be unique');return}Object.values(categoryDraft).forEach(c=>c.label=c.label.trim());Object.entries(categoryMovesDraft).forEach(([from,to])=>state.people.forEach(p=>p.notes.forEach(n=>{if(n.category===from)n.category=to})));categoryDeletesDraft.forEach(key=>state.people.forEach(p=>p.notes=p.notes.filter(n=>n.category!==key)));CATEGORIES=categoryDraft;state.categories=CATEGORIES;state.settings={workspaceName:$('#workspaceName').value.trim()||'QUICK NOTES',workspacePhoto:workspacePhotoDraft,language:$('#languageSetting').value,theme:$('#themeSetting').value,fontSize:$('#fontSizeSetting').value};if(activeFilter!=='all'&&!CATEGORIES[activeFilter])activeFilter='all';save();applySettings();$('#settingsDialog').close();render();toast('Settings saved')};
function restoreBackupData(imported){try{if(!imported||!Array.isArray(imported.people)||!imported.categories)throw new Error();if(!confirm(uiMessage('restoreBackup')))return false;state=imported;state.people.forEach(p=>{p.pinnedCategories=p.pinnedCategories||[];if(p.type==='group')p.memberIds=p.memberIds||[]});state.settings={...DEFAULT_SETTINGS,...(state.settings||{})};state.categories=normalizeCategories(state.categories);CATEGORIES=state.categories;selectedId=state.selectedId||state.people[0]?.id||'';activeFilter='all';save();applySettings();$('#settingsDialog').close();render();toast('Backup restored');return true}catch{toast('This is not a valid Teacher Notes backup');return false}}
