$('#groupForm').onsubmit=e=>{e.preventDefault();const name=$('#groupName').value.trim();if(!name)return;const memberIds=[...document.querySelectorAll('#groupMembers input:checked')].map(x=>x.value);const existing=state.people.find(p=>p.id===$('#groupId').value);if(existing){existing.name=name;existing.description=$('#groupDescription').value.trim();existing.memberIds=memberIds}else{const group={id:crypto.randomUUID(),type:'group',name,description:$('#groupDescription').value.trim(),memberIds,nightForestAvatarColor:randomNightForestAvatarColor(),pinnedCategories:[],notes:[]};state.people.push(group);selectedId=group.id;groupViewSubject='group'}save();$('#groupDialog').close();render();toast(existing?'Group updated':`${name} created`)};
$('#personForm').onsubmit=e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const name=$('#personName').value.trim();if(!name)return;const existing=state.people.find(p=>p.id===$('#personId').value);if(existing){existing.name=name;existing.description=$('#personDescription').value.trim();existing.photo=editingPhoto}else{const p={id:crypto.randomUUID(),type:'individual',name,description:$('#personDescription').value.trim(),photo:editingPhoto,nightForestAvatarColor:randomNightForestAvatarColor(),pinnedCategories:[],notes:[]};state.people.push(p);selectedId=p.id}save();$('#personDialog').close();render();toast(existing?'Student updated':`${name} added`)};
$('#personName').oninput=()=>{if(!editingPhoto)renderPhotoPreview()};
$('#removePhotoBtn').onclick=()=>{editingPhoto='';$('#personPhoto').value='';renderPhotoPreview()};
$('#personPhoto').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Please choose a JPG, PNG or WebP image');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const size=256;const canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d');const scale=Math.max(size/img.width,size/img.height);const width=img.width*scale,height=img.height*scale;ctx.drawImage(img,(size-width)/2,(size-height)/2,width,height);editingPhoto=canvas.toDataURL('image/jpeg',.82);renderPhotoPreview()};img.src=reader.result};reader.readAsDataURL(file)};
function updateNotesSearch(value){searchTerm=String(value||'').trim();$('#searchClearBtn').hidden=!searchTerm;if(searchTerm){activeFilter='all';noteBulkMode=false;noteBulkSelected.clear();const q=searchTerm.toLowerCase(),matches=state.people.filter(p=>p.name.toLowerCase().includes(q)||p.notes.some(n=>n.text.toLowerCase().includes(q)));if(matches.length&&!matches.some(p=>p.id===selectedId))selectedId=matches[0].id}render()}$('#searchInput').oninput=e=>updateNotesSearch(e.target.value);$('#searchClearBtn').onclick=()=>{searchTerm='';$('#searchInput').value='';$('#searchClearBtn').hidden=true;activeFilter='all';render();$('#searchInput').focus()};$('#searchInput').onkeydown=e=>{if(e.key==='Escape'&&searchTerm){e.preventDefault();$('#searchClearBtn').click()}};$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');
$('#workspaceContext').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});
function updateCategoryStripControls(){const viewport=$('#categoryStripViewport'),shell=$('#categoryStripShell'),prev=$('#categoryStripPrev'),next=$('#categoryStripNext');if(!viewport||!shell||!prev||!next)return;const max=Math.max(0,viewport.scrollWidth-viewport.clientWidth),overflowing=max>2,canLeft=overflowing&&viewport.scrollLeft>2,canRight=overflowing&&viewport.scrollLeft<max-2;shell.classList.toggle('is-overflowing',overflowing);prev.hidden=!overflowing;next.hidden=!overflowing;prev.classList.toggle('is-unavailable',!canLeft);next.classList.toggle('is-unavailable',!canRight);prev.disabled=!canLeft;next.disabled=!canRight;prev.setAttribute('aria-hidden',String(!canLeft));next.setAttribute('aria-hidden',String(!canRight));shell.classList.toggle('can-scroll-left',canLeft);shell.classList.toggle('can-scroll-right',canRight)}
function initCategoryStrip(){const viewport=$('#categoryStripViewport'),strip=viewport?.querySelector('.category-strip'),prev=$('#categoryStripPrev'),next=$('#categoryStripNext');categoryStripResizeObserver?.disconnect();categoryStripResizeObserver=null;if(!viewport||!strip||!prev||!next)return;const refresh=()=>requestAnimationFrame(updateCategoryStripControls),step=()=>Math.max(180,Math.round(viewport.clientWidth*.62));prev.onclick=e=>{e.stopPropagation();viewport.scrollBy({left:-step(),behavior:'smooth'})};next.onclick=e=>{e.stopPropagation();viewport.scrollBy({left:step(),behavior:'smooth'})};viewport.addEventListener('scroll',updateCategoryStripControls,{passive:true});viewport.addEventListener('wheel',e=>{if(viewport.scrollWidth<=viewport.clientWidth+2)return;if(Math.abs(e.deltaY)>Math.abs(e.deltaX)){e.preventDefault();viewport.scrollLeft+=e.deltaY}else viewport.scrollLeft+=e.deltaX},{passive:false});let drag=null,suppressClick=false;viewport.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||e.target.closest('button'))return;drag={x:e.clientX,scroll:viewport.scrollLeft,moved:false,pointerId:e.pointerId}});viewport.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pointerId)return;const dx=e.clientX-drag.x;if(!drag.moved&&Math.abs(dx)<5)return;if(!drag.moved){drag.moved=true;viewport.setPointerCapture?.(e.pointerId);viewport.classList.add('is-dragging')}viewport.scrollLeft=drag.scroll-dx});const finishDrag=e=>{if(!drag||e.pointerId!==drag.pointerId)return;suppressClick=drag.moved;viewport.classList.remove('is-dragging');drag=null;if(suppressClick)setTimeout(()=>suppressClick=false,0)};viewport.addEventListener('pointerup',finishDrag);viewport.addEventListener('pointercancel',finishDrag);viewport.addEventListener('click',e=>{if(!suppressClick)return;e.preventDefault();e.stopPropagation()},true);if('ResizeObserver'in window){categoryStripResizeObserver=new ResizeObserver(refresh);categoryStripResizeObserver.observe(viewport);categoryStripResizeObserver.observe(strip)}document.fonts?.ready?.then(refresh);refresh()}

function updateScrollUI(){const topbar=document.querySelector('.topbar'),profile=document.querySelector('.profile-head');$('#floatingAddNote').hidden=true;if(!topbar)return;if(appMode!=='workspace'||!profile||$('#content').hidden){topbar.classList.remove('context-visible');return}const topbarBottom=topbar.getBoundingClientRect().bottom,profileBottom=profile.getBoundingClientRect().bottom;const profileHasLeftView=profileBottom<=topbarBottom+2;topbar.classList.toggle('context-visible',profileHasLeftView)}window.addEventListener('scroll',updateScrollUI,{passive:true});window.addEventListener('resize',updateScrollUI,{passive:true});window.addEventListener('resize',()=>requestAnimationFrame(updateCategoryStripControls),{passive:true});window.addEventListener('resize',()=>{if(appMode==='todo'&&todoView==='current')syncTodoCurrentGeometry()},{passive:true});updateScrollUI();


let lessonWindow=null;
function lessonWindowMarkup(){const initialId=lessonInitialTargetId();return QuickNotesLesson.windowMarkup({targetPickerMarkup:capturePersonPickerMarkup({selectedId:initialId,inputId:'miniPerson',pickerId:'miniPersonPicker'}),categoryMarkup:categoryOptions(captureDefaultCategory())})}
function lessonWindowStyles(){return QuickNotesLesson.windowStyles({theme:state.settings.theme,fontSize:state.settings.fontSize})}
function groupTargetOptions(group){return QuickNotesLesson.groupSubjectOptions({group,people:state.people,language:state.settings.language,escape:esc})}
function mountLessonWindow(win){lessonWindow=win;const doc=win.document,ru=state.settings.language==='ru';let targetId=lessonInitialTargetId();doc.title='Teacher Notes · Lesson Mode';doc.head.innerHTML=`<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>${lessonWindowStyles()}</style>`;doc.body.innerHTML=lessonWindowMarkup();translateUI(doc);const text=doc.querySelector('#miniText'),form=doc.querySelector('#miniForm'),aboutWrap=doc.querySelector('#miniAboutWrap'),about=doc.querySelector('#miniAbout'),status=doc.querySelector('#miniStatus'),addButton=doc.querySelector('.add');const readyText=ru?'Готово для следующей заметки':'Ready for your next note';status.textContent=readyText;const selectTarget=(id)=>{targetId=id||'';addButton.disabled=!targetId;const selected=state.people.find(p=>p.id===targetId),isGroup=selected?.type==='group';doc.body.classList.toggle('group-target',isGroup);aboutWrap.hidden=!isGroup;aboutWrap.style.display=isGroup?'block':'none';about.disabled=!isGroup;if(isGroup){about.innerHTML=groupTargetOptions(selected);if(id===selectedId&&groupViewSubject&&about.querySelector(`option[value="${groupViewSubject}"]`))about.value=groupViewSubject}else about.innerHTML=''};const personPicker=initCapturePersonPicker({root:doc,pickerId:'miniPersonPicker',onChange:selectTarget});selectTarget(personPicker?.value||'');doc.querySelector('#miniClose').onclick=()=>win.close();form.onsubmit=e=>{e.preventDefault();const value=text.value.trim();if(!value||!targetId)return;const resolved=QuickNotesLesson.resolveTarget({people:state.people,contextId:targetId,subjectId:about.value||targetId}),{context,target,valid}=resolved,category=doc.querySelector('#miniCategory').value;if(!valid)return;target.notes.unshift({id:crypto.randomUUID(),category,text:value,createdAt:Date.now(),...(target.type==='individual'&&context.type==='group'?{capturedInGroupId:context.id}:{})});save();text.value='';status.textContent=ru?`Сохранено: ${target.name} · ${CATEGORIES[category].label}`:`Saved to ${target.name} · ${CATEGORIES[category].label}`;status.classList.add('saved');renderNav();if(context.id===selectedId||target.id===selectedId)renderContent();text.focus();setTimeout(()=>{if(!win.closed){status.textContent=readyText;status.classList.remove('saved')}},2200)};text.onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey))form.requestSubmit()};win.addEventListener('pagehide',()=>{personPicker?.destroy();if(lessonWindow===win)lessonWindow=null});text.focus()}
