function updateQuickTarget(id){const wrap=$('#quickAboutWrap'),about=$('#quickAbout'),button=$('#quickForm .quick-add');quickTargetId=id||'';button.disabled=!quickTargetId;const selected=state.people.find(p=>p.id===quickTargetId),isGroup=selected?.type==='group';wrap.hidden=!isGroup;wrap.style.display=isGroup?'block':'none';about.disabled=!isGroup;if(isGroup){about.innerHTML=groupTargetOptions(selected);if(id===selectedId&&groupViewSubject&&about.querySelector(`option[value="${groupViewSubject}"]`))about.value=groupViewSubject}else about.innerHTML=''}
function openOverlayLesson(){const overlay=$('#lessonOverlay'),initialId=lessonInitialTargetId();quickPickerController?.destroy();$('#quickPersonPickerMount').innerHTML=capturePersonPickerMarkup({selectedId:initialId,inputId:'quickPerson',pickerId:'quickPersonPicker'});quickPickerController=initCapturePersonPicker({pickerId:'quickPersonPicker',onChange:updateQuickTarget});$('#quickCategory').innerHTML=categoryOptions(captureDefaultCategory());updateQuickTarget(quickPickerController?.value||'');overlay.hidden=false;translateUI(overlay);setTimeout(()=>$('#quickText').focus(),50)}
$('#lessonBtn').onclick=async()=>{if(IS_DESKTOP&&typeof window.quickNotesDesktop?.openLessonMode==='function'){await window.quickNotesDesktop.openLessonMode();return}if(lessonWindow&&!lessonWindow.closed){lessonWindow.focus();return}try{if('documentPictureInPicture' in window&&window.isSecureContext){const win=await window.documentPictureInPicture.requestWindow({width:440,height:520});mountLessonWindow(win);return}const popup=window.open('','teacher-notes-lesson','popup=yes,width=440,height=520,resizable=yes');if(popup){mountLessonWindow(popup);popup.focus()}else openOverlayLesson()}catch(error){console.warn('Compact Lesson Mode unavailable:',error);openOverlayLesson()}};$('#closeLessonBtn').onclick=()=>$('#lessonOverlay').hidden=true;
$('#quickForm').onsubmit=e=>{e.preventDefault();const text=$('#quickText').value.trim();if(!text||!quickTargetId)return;const resolved=QuickNotesLesson.resolveTarget({people:state.people,contextId:quickTargetId,subjectId:$('#quickAbout').value||quickTargetId}),{context,target,valid}=resolved;if(!valid)return;target.notes.unshift({id:crypto.randomUUID(),category:$('#quickCategory').value,text,createdAt:Date.now(),...(target.type==='individual'&&context.type==='group'?{capturedInGroupId:context.id}:{})});save();$('#quickText').value='';$('#quickConfirm').textContent=state.settings.language==='ru'?`Сохранено: ${target.name} · ${CATEGORIES[$('#quickCategory').value].label}`:`Saved to ${target.name} · ${CATEGORIES[$('#quickCategory').value].label}`;renderNav();if(context.id===selectedId||target.id===selectedId)renderContent();setTimeout(()=>$('#quickConfirm').textContent=state.settings.language==='ru'?'Готово для следующей заметки':'Ready for your next note',2300)};
