function toast(msg){showToast(msg)}
function actionToast(msg,onUndo){showToast(msg,{actionLabel:'Undo',onAction:onUndo,duration:5000})}
function showToast(msg,{actionLabel='',onAction=null,duration=1800}={}){const el=$('#toast');clearTimeout(toast.t);el.replaceChildren();const copy=document.createElement('span');copy.className='toast-copy';copy.textContent=localizedText(msg);el.append(copy);el.classList.toggle('has-action',Boolean(actionLabel&&onAction));if(actionLabel&&onAction){const action=document.createElement('button');action.type='button';action.className='toast-action';action.textContent=localizedText(actionLabel);action.onclick=()=>{clearTimeout(toast.t);el.classList.remove('show','has-action');onAction()};el.append(action)}el.classList.add('show');toast.t=setTimeout(()=>el.classList.remove('show','has-action'),duration)}
