function playDemoNoticeSound(){try{const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;const ctx=new AudioContext();if(ctx.state==='suspended'){ctx.close();return}const start=ctx.currentTime,gain=ctx.createGain();gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.026,start+.05);gain.gain.exponentialRampToValueAtTime(.0001,start+.85);gain.connect(ctx.destination);[[392,0],[523.25,.11]].forEach(([frequency,delay])=>{const tone=ctx.createOscillator();tone.type='sine';tone.frequency.value=frequency;tone.connect(gain);tone.start(start+delay);tone.stop(start+.9)});setTimeout(()=>ctx.close(),1100)}catch{}}
if(!IS_DESKTOP&&!storageAdapter.getFlag('teacher-notes-web-demo-notice'))setTimeout(()=>{const dialog=$('#webDemoDialog');dialog.showModal();requestAnimationFrame(()=>dialog.classList.add('notice-visible'));playDemoNoticeSound()},2500);
